""" Check whether an object is a DataArray.

    Parameters
    ----------
    X : anything
        The object to be checked.

    require_attrs : list of str, optional
        The attributes the object has to have in order to pass as a DataArray.

    Returns
    -------
    bool
        Whether the object is a DataArray or not.
    """
def is_dataarray(X: Any, require_attrs: Any = None) -> object {
    if (require_attrs is None) {
        require_attrs = ["values", "coords", "dims", "to_dataset"];
    }
    return all([hasattr(X, name) for name in require_attrs]);
}

"""
    Generic log message formatter.
    This is a crude initial attempt:  I'm sure we could do much better.

    msg     - is message to be logged
    context - is a string describing the source of the message
              (can be used for filtering)
    level   - indicates the message severity:
              0 - diagnostic, 1 - warning, 2 - error
    """
def FormatLogMessage(msg: Any, context: Any, level: Any) -> object {
    if (level == 0) {
        leveltag = "TRACE";
    } elif (level == 1) {
        leveltag = "INFO";
    } elif (level == 2) {
        leveltag = "WARNING";
    } elif (level == 3) {
        leveltag = "ERROR";
    } else {
        leveltag = "UKNOWN";
    }
    if context {
        context = context + ": ";
    }
    return ("%s%s - %s" % (context, leveltag, msg));
}

