def find_min_recursive(array, left, right):
    """ Find the minimum in rotated array in O(log n) time.
    >>> find_min_recursive([1,2,3,4,5,6], 0, 5)
    1
    >>> find_min_recursive([6, 5, 4, 3, 2, 1], 0, 5)
    1
    >>> find_min_recursive([6, 5, 1, 4, 3, 2], 0, 5)
    1
    """
