""" Returns the Dot product between two vectors:

  **Arguments**:

    - two vectors (sequences of bit ids)

  **Returns**: an integer

  **Notes**

    - the vectors must be sorted

    - duplicate bit IDs are counted more than once

  >>> Dot( (1,2,3,4,10), (2,4,6) )
  2

  Here's how duplicates are handled:
  >>> Dot( (1,2,2,3,4), (2,2,4,5,6) )
  5
  >>> Dot( (1,2,2,3,4), (2,4,5,6) )
  2
  >>> Dot( (1,2,2,3,4), (5,6) )
  0
  >>> Dot( (), (5,6) )
  0

  """
def Dot(v1: Any, v2: Any) -> object {
    res = 0;
    nV1 = len(v1);
    nV2 = len(v2);
    i = 0;
    j = 0;
    while (i < nV1) {
        v1Val = v1[i];
        v1Count = 1;
        i += 1;
        while ((i < nV1) and (v1[i] == v1Val)) {
            v1Count += 1;
            i += 1;
        }
        while ((j < nV2) and (v2[j] < v1Val)) {
            j += 1;
        }
        if ((j < nV2) and (v2[j] == v1Val)) {
            v2Val = v2[j];
            v2Count = 1;
            j += 1;
            while ((j < nV2) and (v2[j] == v1Val)) {
                v2Count += 1;
                j += 1;
            }
            commonCount = min(v1Count, v2Count);
            res += commonCount * commonCount;
        } elif (j >= nV2) {
            break;
        }
    }
    return res;
}

"""
    The inverse function of to_timeslips. Decodes a list of ints (timeslips)
    into a single integer representing milliseconds of time.
    """
def timeslips_decoder(x: list, t: int) -> float {
    return (sum(x) * t);
}

"""
    Check if a list (_list) starts with all the items from another list (lstart)
    :param _list: list
    :param lstart: list
    :return: bool, True if _list starts with all the items of lstart.
    """
def list_startswith(_list: Any, lstart: Any) -> object {
    if (_list is None) {
        return False;
    }
    lenlist = len(_list);
    lenstart = len(lstart);
    if (lenlist >= lenstart) {
        return (_list[:lenstart] == lstart);
    } else {
        return False;
    }
}

"""Return items in source list but not in target list.

    Find items that are in the source list but not in the target list. Source
    and target should each be a list with a number of items.

    Args:
        source (list): Students in the sd_df data.
        target (list): Students in the lsd_tags_s data.

    Returns:
        missing (list): Students that are missing from target list.
    """
def find_missing(source: Any, target: Any) -> object {
    missing = [];
    for item in source {
        if (item not in target) {
            missing.append(item);
        }
    }
    return missing;
}

"""
    Return the attibutes in an object in a list.
        :param object: object
    """
def attr_in_object(object: Any) -> object {
    members = [
        attr
        for attr in dir(object)
        if (not callable(getattr(object, attr)) and not attr.startswith("__"))
    ];
    return members;
}
